import{_ as e,a,b as r,c as o}from"./chunks/network-diagram-3.DuVKc4J7.js";import{_ as i,o as n,c as s,a5 as d}from"./chunks/framework.DGp912Ge.js";const P=JSON.parse('{"title":"Network Configuration Diagram","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/interface/network.md","filePath":"manual/interface/network.md","lastUpdated":1785806767000}'),h={name:"manual/interface/network.md"};function c(u,t,l,g,p,b){return n(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="network-configuration-diagram" tabindex="-1">Network Configuration Diagram <a class="header-anchor" href="#network-configuration-diagram" aria-label="Permalink to &quot;Network Configuration Diagram&quot;">​</a></h1><p>The network layout differs from robot to robot. Two things vary:</p><ul><li><strong>Configuration</strong> — the <strong>research</strong> layout keeps the User PC outside the robot and treats payloads as one generic LAN group. The <strong>industrial</strong> layout mounts the User PC inside the robot and wires each payload individually.</li><li><strong>Router</strong> — some robots have the router <strong>integrated into the switch hub</strong>, so the LTE/5G · Wi-Fi (Mesh) module connects straight to it. Others reach the network through a <strong>separate external router</strong>.</li></ul><p>In every diagram, <strong>R-PC</strong> is the robot&#39;s motion PC and <strong>U-PC</strong> is the user PC. Green lines are LAN, orange lines are WAN.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>The network layout can differ between versions. Please <a href="/RBQ/manual/troubleshooting/error-reporting">contact us</a> if you are unsure which one applies to your robot.</p></div></div><h2 id="research-configuration" tabindex="-1">Research configuration <a class="header-anchor" href="#research-configuration" aria-label="Permalink to &quot;Research configuration&quot;">​</a></h2><p>The U-PC sits outside the robot. LAN payloads — LiDAR, PTZ camera, RTK GPS and so on — share a single connection to the switch hub.</p><h3 id="router-integrated-into-the-switch-hub" tabindex="-1">Router integrated into the switch hub <a class="header-anchor" href="#router-integrated-into-the-switch-hub" aria-label="Permalink to &quot;Router integrated into the switch hub&quot;">​</a></h3><figure><img src="'+e+'" alt="Network configuration diagram, research configuration, router integrated into the switch hub"><figcaption style="text-align:center;">[ Research · Router integrated ]</figcaption></figure><h3 id="separate-external-router" tabindex="-1">Separate external router <a class="header-anchor" href="#separate-external-router" aria-label="Permalink to &quot;Separate external router&quot;">​</a></h3><figure><img src="'+a+'" alt="Network configuration diagram, research configuration, separate external router"><figcaption style="text-align:center;">[ Research · External router ]</figcaption></figure><h2 id="industrial-configuration" tabindex="-1">Industrial configuration <a class="header-anchor" href="#industrial-configuration" aria-label="Permalink to &quot;Industrial configuration&quot;">​</a></h2><p>The U-PC is mounted inside the robot alongside the R-PC, and each payload — LiDAR 1, LiDAR 2, PTZ camera — has its own connection to the switch hub.</p><h3 id="router-integrated-into-the-switch-hub-1" tabindex="-1">Router integrated into the switch hub <a class="header-anchor" href="#router-integrated-into-the-switch-hub-1" aria-label="Permalink to &quot;Router integrated into the switch hub&quot;">​</a></h3><figure><img src="'+r+'" alt="Network configuration diagram, industrial configuration, router integrated into the switch hub"><figcaption style="text-align:center;">[ Industrial · Router integrated ]</figcaption></figure><h3 id="separate-external-router-1" tabindex="-1">Separate external router <a class="header-anchor" href="#separate-external-router-1" aria-label="Permalink to &quot;Separate external router&quot;">​</a></h3><figure><img src="'+o+'" alt="Network configuration diagram, industrial configuration, separate external router"><figcaption style="text-align:center;">[ Industrial · External router ]</figcaption></figure><p>On this layout LiDAR 2 connects through the router rather than directly to the switch hub.</p><h2 id="network-details" tabindex="-1">Network details <a class="header-anchor" href="#network-details" aria-label="Permalink to &quot;Network details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Wi-Fi</td><td>2.4 GHz and 5 GHz</td></tr><tr><td>Network switch speed</td><td>Gigabit Ethernet (1 Gbps)</td></tr><tr><td>Access point</td><td><code>192.168.0.1</code></td></tr></tbody></table><h2 id="onboard-pcs-and-ip-addresses" tabindex="-1">Onboard PCs and IP addresses <a class="header-anchor" href="#onboard-pcs-and-ip-addresses" aria-label="Permalink to &quot;Onboard PCs and IP addresses&quot;">​</a></h2><p>Every robot ships with the Motion PC (R-PC). The Vision PC and the User PC (U-PC) are options — your robot may not have them.</p><table tabindex="0"><thead><tr><th>PC</th><th>IP</th><th>Role</th><th>Fitted</th><th>User access</th></tr></thead><tbody><tr><td>Motion PC (R-PC)</td><td><code>192.168.0.10</code></td><td>Robot control</td><td>Standard</td><td>No</td></tr><tr><td>Vision PC</td><td><code>192.168.0.12</code></td><td>Vision processing</td><td>Option</td><td>No</td></tr><tr><td>User PC (U-PC)</td><td><code>192.168.0.13</code></td><td>Your development work</td><td>Option</td><td>Yes</td></tr></tbody></table><p>The Motion PC and the Vision PC run the robot itself and are not user-accessible. Do your development work on the U-PC.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">If the U-PC does not respond</p><p>The U-PC default address is <code>192.168.0.13</code>. If you cannot connect, attach a monitor to the U-PC and check its current IP. If it is using a different address, set it statically to <code>192.168.0.13</code>.</p></div></div>',25)])])}const w=i(h,[["render",c]]);export{P as __pageData,w as default};
